package UserCache;
use strict;
use warnings;

my %by_name;

sub get_user {
    my ($name) = @_;
    return $by_name{$name};
}

1;

package UserDao;
use strict;
use warnings;

# Look up a user by name.
sub get_user {
    my ($dbh, $name) = @_;
    return $dbh->selectall_arrayref("SELECT id, name FROM users WHERE name = '$name'");
}

1;
